INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_053_M3_S4', 'alteration', '4', 'alteration refers to an agreed change to the terms of an existing contract. In Performance and Discharge, the focus is on the analysis, design, implementation, interpretation, or evaluation of alteration within Contract Law and Commercial Agreements, particularly where the Performance and Discharge module establishes its technical context.', 'SSD_COURSE_053_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M3_S5', 'discharge by agreement', '5', 'discharge by agreement: Ending or varying contractual obligations through mutual agreement of the parties. In Performance and Discharge, the focus is on the analysis, design, implementation, interpretation, or evaluation of discharge by agreement within Contract Law and Commercial Agreements, particularly where the Performance and Discharge module establishes its technical context.', 'SSD_COURSE_053_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M4_S1', 'anticipatory breach', '1', 'anticipatory breach refers to a clear indication before performance is due that a party will not perform a contractual obligation. In Breach and Remedies, the focus is on the analysis, design, implementation, interpretation, or evaluation of anticipatory breach within Contract Law and Commercial Agreements, particularly where the Breach and Remedies module establishes its technical context.', 'SSD_COURSE_053_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M4_S2', 'damages', '2', 'damages: Monetary compensation awarded for legally recognised loss resulting from breach or other actionable conduct. In Breach and Remedies, the focus is on the analysis, design, implementation, interpretation, or evaluation of damages within Contract Law and Commercial Agreements, particularly where the Breach and Remedies module establishes its technical context.', 'SSD_COURSE_053_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M4_S3', 'specific performance', '3', 'specific performance refers to a court-ordered remedy requiring a party to perform a contractual obligation rather than merely pay damages. In Breach and Remedies, the focus is on the analysis, design, implementation, interpretation, or evaluation of specific performance within Contract Law and Commercial Agreements, particularly where the Breach and Remedies module establishes its technical context.', 'SSD_COURSE_053_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M4_S4', 'injunctions', '4', 'injunctions: Court orders requiring a party to do or refrain from doing specified acts, generally used as a legal remedy where the requirements for injunctive relief are satisfied. In Breach and Remedies, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_053_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M4_S5', 'restitution', '5', 'restitution: Restoration of a benefit or value to prevent unjust enrichment or reverse a legally recognised transaction. In Breach and Remedies, the focus is on the analysis, design, implementation, interpretation, or evaluation of restitution within Contract Law and Commercial Agreements, particularly where the Breach and Remedies module establishes its technical context.', 'SSD_COURSE_053_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M5_S1', 'indemnities', '1', 'indemnities: Contractual promises to compensate another party for specified losses or liabilities. In Commercial Risk Allocation, the focus is on the analysis, design, implementation, interpretation, or evaluation of indemnities within Contract Law and Commercial Agreements, particularly where the Commercial Risk Allocation module establishes its technical context.', 'SSD_COURSE_053_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M5_S2', 'limitation clauses', '2', 'limitation clauses: Terms that cap the amount or extent of contractual liability. In Commercial Risk Allocation, the focus is on the analysis, design, implementation, interpretation, or evaluation of limitation clauses within Contract Law and Commercial Agreements, particularly where the Commercial Risk Allocation module establishes its technical context.', 'SSD_COURSE_053_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M5_S3', 'guarantees', '3', 'guarantees: Promises by one party to answer for specified obligations or default of another party, subject to applicable law. In Commercial Risk Allocation, the focus is on the analysis, design, implementation, interpretation, or evaluation of guarantees within Contract Law and Commercial Agreements, particularly where the Commercial Risk Allocation module establishes its technical context.', 'SSD_COURSE_053_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M5_S4', 'force majeure', '4', 'force majeure refers to a contractual mechanism addressing specified extraordinary events that prevent or materially hinder performance. In Commercial Risk Allocation, the focus is on the analysis, design, implementation, interpretation, or evaluation of force majeure within Contract Law and Commercial Agreements, particularly where the Commercial Risk Allocation module establishes its technical context.', 'SSD_COURSE_053_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M5_S5', 'insurance clauses', '5', 'insurance clauses: Contract terms allocating requirements for insurance coverage, limits, evidence, and responsibility for risks. In Commercial Risk Allocation, the focus is on the analysis, design, implementation, interpretation, or evaluation of insurance clauses within Contract Law and Commercial Agreements, particularly where the Commercial Risk Allocation module establishes its technical context.', 'SSD_COURSE_053_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M6_S1', 'definitions', '1', 'definitions: Contract provisions that assign specific meanings to words or phrases used in the agreement. In Contract Drafting and Negotiation, the focus is on the analysis, design, implementation, interpretation, or evaluation of definitions within Contract Law and Commercial Agreements, particularly where the Contract Drafting and Negotiation module establishes its technical context.', 'SSD_COURSE_053_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M6_S2', 'representations', '2', 'representations: Statements of fact or other assertions made in connection with entering a contract that may have legal consequences if false. In Contract Drafting and Negotiation, the focus is on the analysis, design, implementation, interpretation, or evaluation of representations within Contract Law and Commercial Agreements, particularly where the Contract Drafting and Negotiation module establishes its technical context.', 'SSD_COURSE_053_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M6_S3', 'covenants', '3', 'covenants: Contractual promises requiring a party to do or refrain from doing specified acts. In Contract Drafting and Negotiation, the focus is on the analysis, design, implementation, interpretation, or evaluation of covenants within Contract Law and Commercial Agreements, particularly where the Contract Drafting and Negotiation module establishes its technical context.', 'SSD_COURSE_053_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M6_S4', 'schedules', '4', 'schedules: Attached contractual documents containing detailed specifications, procedures, prices, deliverables, or other agreed information. In Contract Drafting and Negotiation, the focus is on the analysis, design, implementation, interpretation, or evaluation of schedules within Contract Law and Commercial Agreements, particularly where the Contract Drafting and Negotiation module establishes its technical context.', 'SSD_COURSE_053_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M6_S5', 'negotiation strategy', '5', 'negotiation strategy: Planned approaches for balancing legal rights, commercial interests, risks, concessions, and bargaining objectives. In Contract Drafting and Negotiation, the focus is on the analysis, design, implementation, interpretation, or evaluation of negotiation strategy within Contract Law and Commercial Agreements, particularly where the Contract Drafting and Negotiation module establishes its technical context.', 'SSD_COURSE_053_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M7_S1', 'sale of goods', '1', 'sale of goods: Contractual transactions involving the transfer of goods from seller to buyer for agreed consideration. In Commercial Agreements in Practice, the focus is on the analysis, design, implementation, interpretation, or evaluation of sale of goods within Contract Law and Commercial Agreements, particularly where the Commercial Agreements in Practice module establishes its technical context.', 'SSD_COURSE_053_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M7_S2', 'services', '2', 'services: Contractual arrangements under which one party performs specified activities or delivers defined services for another. In Commercial Agreements in Practice, the focus is on the analysis, design, implementation, interpretation, or evaluation of services within Contract Law and Commercial Agreements, particularly where the Commercial Agreements in Practice module establishes its technical context.', 'SSD_COURSE_053_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M7_S3', 'technology agreements', '3', 'technology agreements: Commercial contracts governing software, technology products, intellectual property, data, licensing, development, or related services. In Commercial Agreements in Practice, the focus is on the analysis, design, implementation, interpretation, or evaluation of technology agreements within Contract Law and Commercial Agreements, particularly where the Commercial Agreements in Practice module establishes its technical context.', 'SSD_COURSE_053_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M7_S4', 'confidentiality', '4', 'confidentiality: Obligation or practice of preventing unauthorized access, use, or disclosure of information that is subject to a defined confidentiality requirement. In Commercial Agreements in Practice, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_053_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_053_M7_S5', 'dispute clauses', '5', 'dispute clauses: Contract provisions specifying procedures, forums, governing law, escalation, arbitration, or litigation for resolving disputes. In Commercial Agreements in Practice, the focus is on the analysis, design, implementation, interpretation, or evaluation of dispute clauses within Contract Law and Commercial Agreements, particularly where the Commercial Agreements in Practice module establishes its technical context.', 'SSD_COURSE_053_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M1_S1', 'employment status', '1', 'employment status refers to the legal classification of a worker or working relationship, which affects applicable rights, duties, and protections. In Employment Relationship and Conditions, the focus is on the analysis, design, implementation, interpretation, or evaluation of employment status within Labour and Employment Law, particularly where the Employment Relationship and Conditions module establishes its technical context.', 'SSD_COURSE_054_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M1_S2', 'appointment terms', '2', 'appointment terms: Terms governing appointment to employment, including role, remuneration, duration, duties, and other agreed conditions. In Employment Relationship and Conditions, the focus is on the analysis, design, implementation, interpretation, or evaluation of appointment terms within Labour and Employment Law, particularly where the Employment Relationship and Conditions module establishes its technical context.', 'SSD_COURSE_054_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M1_S3', 'working conditions', '3', 'working conditions: Rules and contractual conditions governing the environment, organisation, and terms under which employees work. In Employment Relationship and Conditions, the focus is on the analysis, design, implementation, interpretation, or evaluation of working conditions within Labour and Employment Law, particularly where the Employment Relationship and Conditions module establishes its technical context.', 'SSD_COURSE_054_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M1_S4', 'standing orders', '4', 'standing orders: Formal workplace rules governing employment conditions, conduct, discipline, and related matters where legally required. In Employment Relationship and Conditions, the focus is on the analysis, design, implementation, interpretation, or evaluation of standing orders within Labour and Employment Law, particularly where the Employment Relationship and Conditions module establishes its technical context.', 'SSD_COURSE_054_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M2_S1', 'wage regulation', '1', 'wage regulation: Rules governing minimum or protected wage levels, wage payment, deductions, and related employer obligations. In Wages and Benefits, the focus is on the analysis, design, implementation, interpretation, or evaluation of wage regulation within Labour and Employment Law, particularly where the Wages and Benefits module establishes its technical context.', 'SSD_COURSE_054_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M2_S2', 'deductions', '2', 'deductions: Amounts lawfully withheld from wages or other employee payments under specified rules or authorisation. In Wages and Benefits, the focus is on the analysis, design, implementation, interpretation, or evaluation of deductions within Labour and Employment Law, particularly where the Wages and Benefits module establishes its technical context.', 'SSD_COURSE_054_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M2_S3', 'bonus', '3', 'bonus: Additional remuneration paid or required under applicable employment terms or law, often linked to performance or statutory schemes. In Wages and Benefits, the focus is on the analysis, design, implementation, interpretation, or evaluation of bonus within Labour and Employment Law, particularly where the Wages and Benefits module establishes its technical context.', 'SSD_COURSE_054_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M2_S4', 'social security', '4', 'social security: Systems that provide income or related protection against risks such as sickness, disability, unemployment, old age, or family contingencies. In Wages and Benefits, the focus is on the analysis, design, implementation, interpretation, or evaluation of social security within Labour and Employment Law, particularly where the Wages and Benefits module establishes its technical context.', 'SSD_COURSE_054_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M2_S5', 'leave', '5', 'leave: Authorised absence from work governed by eligibility, duration, pay, accrual, and procedural rules. In Wages and Benefits, the focus is on the analysis, design, implementation, interpretation, or evaluation of leave within Labour and Employment Law, particularly where the Wages and Benefits module establishes its technical context.', 'SSD_COURSE_054_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M3_S1', 'trade unions', '1', 'trade unions: Organisations formed to represent workers'' collective interests in employment and industrial relations. In Industrial Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of trade unions within Labour and Employment Law, particularly where the Industrial Relations module establishes its technical context.', 'SSD_COURSE_054_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M3_S2', 'collective bargaining', '2', 'collective bargaining: Negotiation between employers and worker representatives over wages, conditions, and other employment matters. In Industrial Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of collective bargaining within Labour and Employment Law, particularly where the Industrial Relations module establishes its technical context.', 'SSD_COURSE_054_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M3_S3', 'industrial disputes', '3', 'industrial disputes: Disagreements between employers and workers or their representatives concerning employment, work conditions, or industrial relations. In Industrial Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of industrial disputes within Labour and Employment Law, particularly where the Industrial Relations module establishes its technical context.', 'SSD_COURSE_054_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M3_S4', 'strikes and lockouts', '4', 'strikes and lockouts: Collective actions in which workers withhold labour or employers temporarily exclude workers within the limits of applicable law. In Industrial Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of strikes and lockouts within Labour and Employment Law, particularly where the Industrial Relations module establishes its technical context.', 'SSD_COURSE_054_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M4_S1', 'workplace safety', '1', 'workplace safety: Legal and organisational measures intended to prevent work-related injury, illness, and unsafe conditions. In Occupational and Workplace Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of workplace safety within Labour and Employment Law, particularly where the Occupational and Workplace Regulation module establishes its technical context.', 'SSD_COURSE_054_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M4_S2', 'working hours', '2', 'working hours: Rules governing normal hours, overtime, rest periods, shifts, and related limits on working time. In Occupational and Workplace Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of working hours within Labour and Employment Law, particularly where the Occupational and Workplace Regulation module establishes its technical context.', 'SSD_COURSE_054_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M4_S3', 'welfare', '3', 'welfare: Workplace measures and statutory benefits intended to support employee health, safety, wellbeing, or social protection. In Occupational and Workplace Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of welfare within Labour and Employment Law, particularly where the Occupational and Workplace Regulation module establishes its technical context.', 'SSD_COURSE_054_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M4_S4', 'employer duties', '4', 'employer duties: Legal obligations imposed on employers concerning wages, safety, equality, records, benefits, and other employment matters. In Occupational and Workplace Regulation, the focus is on the analysis, design, implementation, interpretation, or evaluation of employer duties within Labour and Employment Law, particularly where the Occupational and Workplace Regulation module establishes its technical context.', 'SSD_COURSE_054_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M5_S1', 'non-discrimination', '1', 'non-discrimination: Legal requirements prohibiting unjustified adverse treatment based on protected characteristics in employment. In Equality and Workplace Rights, the focus is on the analysis, design, implementation, interpretation, or evaluation of non-discrimination within Labour and Employment Law, particularly where the Equality and Workplace Rights module establishes its technical context.', 'SSD_COURSE_054_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M5_S2', 'harassment', '2', 'harassment: Unwelcome conduct that violates applicable workplace protections or creates a prohibited hostile or degrading work environment. In Equality and Workplace Rights, the focus is on the analysis, design, implementation, interpretation, or evaluation of harassment within Labour and Employment Law, particularly where the Equality and Workplace Rights module establishes its technical context.', 'SSD_COURSE_054_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M5_S3', 'maternity protections', '3', 'maternity protections: Employment protections concerning pregnancy, childbirth, maternity leave, benefits, and protection against discrimination or adverse treatment. In Equality and Workplace Rights, the focus is on the analysis, design, implementation, interpretation, or evaluation of maternity protections within Labour and Employment Law, particularly where the Equality and Workplace Rights module establishes its technical context.', 'SSD_COURSE_054_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M5_S4', 'reasonable workplace protections', '4', 'reasonable workplace protections: Measures and legal duties intended to provide appropriate protection or accommodation for workers in specified workplace circumstances. In Equality and Workplace Rights, the focus is on the analysis, design, implementation, interpretation, or evaluation of reasonable workplace protections within Labour and Employment Law, particularly where the Equality and Workplace Rights module establishes its technical context.', 'SSD_COURSE_054_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M6_S1', 'conciliation', '1', 'conciliation refers to a dispute-resolution process in which a neutral third party helps parties seek a mutually acceptable settlement. In Dispute Resolution and Adjudication, the focus is on the analysis, design, implementation, interpretation, or evaluation of conciliation within Labour and Employment Law, particularly where the Dispute Resolution and Adjudication module establishes its technical context.', 'SSD_COURSE_054_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M6_S2', 'labour authorities', '2', 'labour authorities: Public institutions responsible for administering, inspecting, mediating, or enforcing labour and employment requirements. In Dispute Resolution and Adjudication, the focus is on the analysis, design, implementation, interpretation, or evaluation of labour authorities within Labour and Employment Law, particularly where the Dispute Resolution and Adjudication module establishes its technical context.', 'SSD_COURSE_054_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M6_S3', 'tribunals', '3', 'tribunals: Specialized adjudicatory bodies established under law to determine specified classes of disputes, claims, or regulatory matters within their statutory jurisdiction. In Dispute Resolution and Adjudication, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_054_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M6_S4', 'judicial remedies', '4', 'judicial remedies: judicial remedies in Labour and Employment Law concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing judicial remedies. In Dispute Resolution and Adjudication, the focus is on the analysis, design, implementation, interpretation, or evaluation of judicial remedies within Labour and Employment Law, particularly where the Dispute Resolution and Adjudication module establishes its technical context.', 'SSD_COURSE_054_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M7_S1', 'platform work', '1', 'platform work: Work arranged or mediated through digital platforms, raising questions about worker status, rights, and regulatory coverage. In Contemporary Employment Issues, the focus is on the analysis, design, implementation, interpretation, or evaluation of platform work within Labour and Employment Law, particularly where the Contemporary Employment Issues module establishes its technical context.', 'SSD_COURSE_054_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M7_S2', 'fixed-term work', '2', 'fixed-term work: Employment for a specified period or until a defined event, subject to applicable rules on duration and renewal. In Contemporary Employment Issues, the focus is on the analysis, design, implementation, interpretation, or evaluation of fixed-term work within Labour and Employment Law, particularly where the Contemporary Employment Issues module establishes its technical context.', 'SSD_COURSE_054_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_054_M7_S3', 'contract labour', '3', 'contract labour: Work performed through a contractual intermediary or labour contractor rather than direct employment by the principal entity. In Contemporary Employment Issues, the focus is on the analysis, design, implementation, interpretation, or evaluation of contract labour within Labour and Employment Law, particularly where the Contemporary Employment Issues module establishes its technical context.', 'SSD_COURSE_054_M7_S3', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;